import type { QuestionWithStudent, StudentSummary } from "../types";

const ANON_STICKERS = ["🦊", "🐼", "🦉", "🐯", "🐬", "🦄", "🐝", "🐢", "🦋", "🐙"];

function pickSticker(id: number): string {
  return ANON_STICKERS[(id - 1) % ANON_STICKERS.length];
}

export function formatAnonLabel(studentId: number): string {
  return `anon-${studentId} ${pickSticker(studentId)}`;
}

export function formatStudentSummary(student: StudentSummary): string {
  return formatAnonLabel(student.id);
}

export function formatQuestionStudent(question: QuestionWithStudent): string {
  return formatAnonLabel(question.studentId);
}
```

